from datetime import timedelta
from zoneinfo import ZoneInfo

NY = ZoneInfo("America/New_York")

def next_day_same_time(dt):
    wall = dt.astimezone(NY).replace(tzinfo=None) + timedelta(days=1)
    return wall.replace(tzinfo=NY)

